<script setup lang="ts">
import type { EChartsCoreOption } from "echarts/core";
import { appNavItems } from "~/utils/app-nav";
import { resolveApiErrorMessage } from "~/utils/api-errors";
import { formatAppDateTime } from "~/utils/date-format";

type Detail = {
	store: { id: string; name: string; store_type: string; currency: string; business_day_start_minutes: number };
	dashboard: any; stock: any; purchasing: any; products: any;
};
const route = useRoute();
const { apiFetch } = useApiClient();
const preset = ref(String(route.query.preset || "today"));
const dateFrom = ref(String(route.query.date_from || ""));
const dateTo = ref(String(route.query.date_to || ""));
const loading = ref(true);
const refreshing = ref(false);
const error = ref("");
const report = ref<Detail | null>(null);
const tabs = [
	{ id: "sales", label: "ຍອດຂາຍ" },
	{ id: "products", label: "ສິນຄ້າ" },
	{ id: "stock", label: "ສະຕັອກ" },
	{ id: "purchasing", label: "ການຈັດຊື້" },
	{ id: "promotions", label: "ໂປຣໂມຊັນ" },
	{ id: "operations", label: "ການດຳເນີນງານ" },
];
const activeTab = ref("sales");
const presets = [ { id: "today", label: "ມື້ນີ້" }, { id: "yesterday", label: "ມື້ວານ" }, { id: "this_week", label: "ອາທິດນີ້" }, { id: "last_week", label: "ອາທິດກ່ອນ" }, { id: "this_month", label: "ເດືອນນີ້" }, { id: "last_month", label: "ເດືອນກ່ອນ" }, { id: "custom", label: "ກຳນົດເອງ" } ];
const currency = computed(() => report.value?.store.currency || "LAK");
function money(value: number) {
	const formatted = new Intl.NumberFormat("lo-LA", { maximumFractionDigits: 0 }).format(value || 0);
	return currency.value === "LAK" ? `${formatted}₭` : new Intl.NumberFormat("lo-LA", { style: "currency", currency: currency.value, maximumFractionDigits: 0 }).format(value || 0);
}
function number(value: number) { return new Intl.NumberFormat("lo-LA").format(value || 0); }
const compactNumber = (value: number) => new Intl.NumberFormat("lo-LA", { notation: "compact", maximumFractionDigits: 1 }).format(value || 0);
const commonTooltip = { trigger: "axis", axisPointer: { type: "cross" }, valueFormatter: (value: unknown) => money(Number(value)) };
const salesOption = computed<EChartsCoreOption>(() => ({
	color: ["#10b981", "#3b82f6"], tooltip: commonTooltip, legend: { bottom: 0, data: ["ຍອດຂາຍ", "ຈຳນວນບິນ"] }, grid: { left: 12, right: 18, top: 24, bottom: 54, containLabel: true },
	xAxis: { type: "category", data: report.value?.dashboard.sales_series.map((item: any) => item.label) || [] }, yAxis: [{ type: "value", axisLabel: { formatter: compactNumber }, splitLine: { lineStyle: { color: "#f5f5f4" } } }, { type: "value", splitLine: { show: false } }],
	series: [{ name: "ຍອດຂາຍ", type: "line", smooth: true, symbol: "circle", symbolSize: 7, areaStyle: { color: "rgba(16,185,129,.14)" }, data: report.value?.dashboard.sales_series.map((item: any) => item.revenue) || [] }, { name: "ຈຳນວນບິນ", type: "bar", yAxisIndex: 1, barMaxWidth: 18, itemStyle: { color: "rgba(59,130,246,.35)", borderRadius: [4, 4, 0, 0] }, data: report.value?.dashboard.sales_series.map((item: any) => item.bill_count) || [] }],
}));
const profitOption = computed<EChartsCoreOption>(() => ({
	color: ["#f59e0b", "#10b981", "#a8a29e"], tooltip: commonTooltip, legend: { bottom: 0 }, grid: { left: 10, right: 10, top: 24, bottom: 48, containLabel: true }, xAxis: { type: "category", data: report.value?.dashboard.sales_series.map((item: any) => item.label) || [] }, yAxis: { type: "value", axisLabel: { formatter: compactNumber }, splitLine: { lineStyle: { color: "#f5f5f4" } } },
	series: [["ຕົ້ນທຶນ", "known_cost"], ["ກຳໄລ", "gross_profit"], ["ບໍ່ຮູ້ຕົ້ນທຶນ", "unknown_cost_revenue"]].map(([name, key]) => ({ name, type: "bar", stack: "total", barMaxWidth: 26, data: report.value?.dashboard.sales_series.map((item: any) => item[key]) || [] })),
}));
const paymentOption = computed<EChartsCoreOption>(() => ({ color: ["#10b981", "#3b82f6", "#8b5cf6", "#f59e0b", "#a8a29e"], tooltip: { trigger: "item", formatter: (item: any) => `${item.name}<br/>${money(item.value)} · ${item.percent}%` }, legend: { bottom: 0, type: "scroll" }, series: [{ type: "pie", radius: ["48%", "72%"], center: ["50%", "43%"], padAngle: 2, itemStyle: { borderRadius: 5, borderColor: "#fff", borderWidth: 2 }, label: { show: false }, data: report.value?.dashboard.payment_mix.map((item: any) => ({ name: item.method, value: item.amount })) || [] }] }));
const stockMovementOption = computed<EChartsCoreOption>(() => ({ color: ["#10b981", "#3b82f6", "#f59e0b"], tooltip: { trigger: "axis" }, legend: { bottom: 0 }, grid: { left: 10, right: 16, top: 24, bottom: 48, containLabel: true }, xAxis: { type: "category", data: report.value?.stock.movement_series.map((item: any) => item.label) || [] }, yAxis: { type: "value", minInterval: 1, splitLine: { lineStyle: { color: "#f5f5f4" } } }, series: [{ name: "ຮັບເຂົ້າ", type: "bar", barMaxWidth: 22, data: report.value?.stock.movement_series.map((item: any) => item.in_qty) || [] }, { name: "ຂາຍອອກ", type: "bar", stack: "out", barMaxWidth: 22, data: report.value?.stock.movement_series.map((item: any) => item.sold_qty) || [] }, { name: "ປັບອອກ", type: "bar", stack: "out", barMaxWidth: 22, data: report.value?.stock.movement_series.map((item: any) => item.out_qty) || [] }] }));
const purchasingOption = computed<EChartsCoreOption>(() => ({ color: ["#6366f1"], tooltip: commonTooltip, grid: { left: 10, right: 10, top: 24, bottom: 32, containLabel: true }, xAxis: { type: "category", data: report.value?.purchasing.spend_series.map((item: any) => item.label) || [] }, yAxis: { type: "value", axisLabel: { formatter: compactNumber }, splitLine: { lineStyle: { color: "#f5f5f4" } } }, series: [{ name: "ຍອດຈັດຊື້", type: "line", smooth: true, symbol: "circle", symbolSize: 7, areaStyle: { color: "rgba(99,102,241,.14)" }, data: report.value?.purchasing.spend_series.map((item: any) => item.total_spend) || [] }] }));
const productOption = computed<EChartsCoreOption>(() => { const rows = [...(report.value?.dashboard.top_products || [])].slice(0, 8).reverse(); return { color: ["#10b981"], tooltip: commonTooltip, grid: { left: 8, right: 24, top: 8, bottom: 20, containLabel: true }, xAxis: { type: "value", axisLabel: { formatter: compactNumber }, splitLine: { lineStyle: { color: "#f5f5f4" } } }, yAxis: { type: "category", data: rows.map((item: any) => item.name), axisLabel: { width: 110, overflow: "truncate" } }, series: [{ type: "bar", barMaxWidth: 18, itemStyle: { borderRadius: [0, 5, 5, 0] }, data: rows.map((item: any) => item.revenue) }] }; });
const promotionValueOption = computed<EChartsCoreOption>(() => { const rows = report.value?.dashboard.promotion_performance || []; return { color: ["#f59e0b", "#8b5cf6"], tooltip: commonTooltip, legend: { bottom: 0 }, grid: { left: 10, right: 16, top: 24, bottom: 52, containLabel: true }, xAxis: { type: "category", data: rows.map((item: any) => item.promotion_name), axisLabel: { width: 110, overflow: "truncate" } }, yAxis: { type: "value", axisLabel: { formatter: compactNumber }, splitLine: { lineStyle: { color: "#f5f5f4" } } }, series: [{ name: "ສ່ວນຫຼຸດ", type: "bar", barMaxWidth: 24, data: rows.map((item: any) => item.discount_amount) }, { name: "ຕົ້ນທຶນຂອງແຖມ", type: "bar", barMaxWidth: 24, data: rows.map((item: any) => item.gift_cost) }] }; });
const promotionUsageOption = computed<EChartsCoreOption>(() => { const rows = report.value?.dashboard.promotion_performance || []; return { color: ["#10b981", "#3b82f6"], tooltip: { trigger: "axis" }, legend: { bottom: 0 }, grid: { left: 10, right: 16, top: 24, bottom: 52, containLabel: true }, xAxis: { type: "category", data: rows.map((item: any) => item.promotion_name), axisLabel: { width: 110, overflow: "truncate" } }, yAxis: { type: "value", minInterval: 1, splitLine: { lineStyle: { color: "#f5f5f4" } } }, series: [{ name: "ບິນ", type: "bar", barMaxWidth: 24, data: rows.map((item: any) => item.bill_count) }, { name: "ນຳໃຊ້", type: "bar", barMaxWidth: 24, data: rows.map((item: any) => item.applications) }] }; });
const heatmapOption = computed<EChartsCoreOption>(() => { const values = report.value?.dashboard.heatmap.map((item: any) => [item.hour, item.weekday, item.revenue]) || []; const maximum = Math.max(1, ...values.map((value: any) => Number(value[2]))); const weekdays = ["ຈັນ", "ອັງຄານ", "ພຸດ", "ພະຫັດ", "ສຸກ", "ເສົາ", "ອາທິດ"]; return { tooltip: { formatter: (item: any) => `${weekdays[item.value[1]]} ${String(item.value[0]).padStart(2, "0")}:00<br/>${money(item.value[2])}` }, grid: { left: 12, right: 20, top: 10, bottom: 42, containLabel: true }, xAxis: { type: "category", data: Array.from({ length: 24 }, (_, index) => String(index).padStart(2, "0")), splitArea: { show: true } }, yAxis: { type: "category", data: weekdays, splitArea: { show: true } }, visualMap: { min: 0, max: maximum, calculable: false, orient: "horizontal", left: "center", bottom: 0, inRange: { color: ["#ecfdf5", "#6ee7b7", "#059669"] } }, series: [{ type: "heatmap", data: values, itemStyle: { borderColor: "#fff", borderWidth: 2 } }] }; });
function periodText() { const p = report.value?.dashboard?.period; if (!p) return ""; const f = (value: string) => formatAppDateTime(value, "lo"); return `${f(p.from)} – ${f(new Date(new Date(p.to).getTime() - 1).toISOString())}`; }
function query() { const p = new URLSearchParams({ preset: preset.value, timezone_offset: "420" }); if (preset.value === "custom") { p.set("date_from", dateFrom.value); p.set("date_to", dateTo.value); } return p.toString(); }
async function load(options?: { refresh?: boolean }) { if (preset.value === "custom" && (!dateFrom.value || !dateTo.value)) return; if (options?.refresh) refreshing.value = true; else loading.value = true; error.value = ""; try { report.value = (await apiFetch<{ data: Detail }>(`/system-admin/reports/${encodeURIComponent(String(route.params.storeId))}?${query()}`)).data; } catch (cause) { error.value = resolveApiErrorMessage(cause, "ໂຫຼດລາຍງານຮ້ານບໍ່ສຳເລັດ"); } finally { loading.value = false; refreshing.value = false; } }
function selectPreset(id: string) { preset.value = id; if (id !== "custom") void load(); }
onMounted(() => void load());
</script>

<template>
	<AppSidebarShell :nav-items="appNavItems" :active-ids="['system-reports']" sidebar-eyebrow="ລະບົບ" sidebar-title="ຜູ້ດູແລລະບົບ" sidebar-compact-title="SYS" sidebar-description="ລາຍງານຂ້າມຮ້ານສຳລັບຜູ້ດູແລລະບົບ">
		<template #default="{ openSidebar }"><div class="min-w-0 space-y-3 pb-6">
			<AppPageHeader :title="report?.store.name || 'ລາຍງານຮ້ານ'" description="ລາຍງານສະເພາະຮ້ານນີ້ ຈາກພື້ນທີ່ System Admin" :title-badge="false" compact body-class="px-3 py-2.5 sm:px-4 sm:py-3" :tablet-layout="true" @menu="openSidebar"><template #actions><NuxtLink to="/system-admin/reports"><AppButton color="neutral" variant="soft" icon="i-heroicons-arrow-left-20-solid">ກັບໄປລາຍຊື່ຮ້ານ</AppButton></NuxtLink><AppButton color="neutral" variant="soft" icon="i-heroicons-arrow-path-20-solid" :loading="refreshing" @click="load({ refresh: true })">ໂຫຼດໃໝ່</AppButton></template></AppPageHeader>
			<section class="rounded-md border border-neutral-200 bg-white p-4 shadow-sm">
				<div class="flex flex-col gap-4 xl:flex-row xl:items-start xl:justify-between">
					<div class="min-w-0">
						<h2 class="text-base font-semibold text-stone-950">ຊ່ວງລາຍງານ</h2>
						<p v-if="report" class="mt-1 text-sm text-stone-500">{{ periodText() }}</p>
						<p class="mt-1 text-xs text-stone-400">ຮອບວັນເລີ່ມ {{ report ? `${String(Math.floor(report.store.business_day_start_minutes / 60)).padStart(2, '0')}:${String(report.store.business_day_start_minutes % 60).padStart(2, '0')}` : '—' }}</p>
					</div>
					<div class="flex max-w-full flex-wrap gap-2 xl:max-w-[44rem] xl:justify-end">
						<AppButton v-for="item in presets" :key="item.id" size="sm" :color="preset === item.id ? 'primary' : 'neutral'" :variant="preset === item.id ? 'solid' : 'soft'" @click="selectPreset(item.id)">{{ item.label }}</AppButton>
					</div>
				</div>
				<div v-if="preset === 'custom'" class="mt-4 flex flex-col gap-3 border-t border-neutral-100 pt-4 lg:flex-row lg:items-end lg:justify-end">
					<AppDateRangePicker v-model:from="dateFrom" v-model:to="dateTo" :from-label="'ຈາກວັນທີ'" :to-label="'ເຖິງວັນທີ'" :select-label="'ເລືອກວັນທີ'" />
					<AppButton color="primary" class="lg:mb-0" @click="load()">ນຳໃຊ້</AppButton>
				</div>
			</section>
			<div v-if="loading" class="min-h-[320px] rounded-md border border-neutral-200 bg-white"><AppInlineLoadingBar container-class="bg-neutral-100" /></div><div v-else-if="error" class="rounded-md border border-rose-200 bg-rose-50 p-5 text-center text-sm text-rose-700">{{ error }}</div>
			<template v-else-if="report"><div class="flex gap-1 overflow-x-auto rounded-md border border-neutral-200 bg-white p-1.5 shadow-sm"><AppButton v-for="tab in tabs" :key="tab.id" size="sm" :variant="activeTab === tab.id ? 'solid' : 'ghost'" @click="activeTab = tab.id">{{ tab.label }}</AppButton></div>
				<div v-if="activeTab === 'sales'" class="space-y-3"><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><UCard v-for="item in [{label:'ຍອດຂາຍສຸດທິ',value:money(report.dashboard.summary.revenue)},{label:'ຕົ້ນທຶນທີ່ຮູ້',value:money(report.dashboard.profitability.known_cost)},{label:'ກຳໄລຂັ້ນຕົ້ນ',value:money(report.dashboard.summary.gross_profit)},{label:'ຈຳນວນບິນ',value:number(report.dashboard.summary.bill_count)}]" :key="item.label"><p class="text-xs text-stone-500">{{ item.label }}</p><p class="mt-2 text-xl font-semibold text-stone-950">{{ item.value }}</p></UCard></div><UCard><div class="flex items-start justify-between gap-3"><div><h2 class="font-semibold">ຂໍ້ມູນຕົ້ນທຶນ</h2><p class="mt-1 text-sm text-stone-500">ກຳໄລຈະເຊື່ອຖືໄດ້ຕາມຄວາມຄົບຂອງຕົ້ນທຶນ</p></div><span class="text-lg font-semibold text-emerald-700">{{ report.dashboard.profitability.cost_coverage_percent.toFixed(1) }}%</span></div><div class="mt-4 grid gap-3 sm:grid-cols-3"><div><p class="text-xs text-stone-500">ຍອດຂາຍບໍ່ມີຕົ້ນທຶນ</p><p class="mt-1 font-semibold">{{ money(report.dashboard.profitability.unknown_cost_revenue) }}</p></div><div><p class="text-xs text-stone-500">ສ່ວນຫຼຸດ</p><p class="mt-1 font-semibold">{{ money(report.dashboard.summary.discount) }}</p></div><div><p class="text-xs text-stone-500">VAT</p><p class="mt-1 font-semibold">{{ money(report.dashboard.summary.vat_amount) }}</p></div></div></UCard></div>
