ad><tbody><tr v-for="item in report.stock.movement_series" :key="item.label" class="border-b border-neutral-100"><td class="py-2">{{ item.label }}</td><td class="py-2 text-right text-emerald-700">+{{ number(item.in_qty) }}</td><td class="py-2 text-right">−{{ number(item.sold_qty) }}</td><td class="py-2 text-right text-amber-700">−{{ number(item.out_qty) }}</td></tr></tbody></table></div></UCard></div>
